  (uuid_generate_v4(), 'handmade-mohave-turquoise-sterling-silver-bangle-gemstone-cuff-bracelet', '4382588197', 'https://www.etsy.com/listing/4382588197/handmade-mohave-turquoise-sterling?click_key=EuUlOSE-W4_A3Il7jOcu-QwYWWee%3ALT9ce3cf38716dd069650b5593bf138be25f6fd122&click_sum=a13eb460&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=turquoise+jewelry&ref=search_grid-969537-15-8&sr_prefetch=1&pf_from=search&pro=1&frs=1&pop=1',
