  (uuid_generate_v4(), 'vintage-sterling-semi-precious-inlay-earrings-2', '1665502472', 'https://www.etsy.com/listing/1665502472/vintage-sterling-semi-precious-inlay?click_key=2ed48753-436f-4083-9571-6ba7e17e2d61%3ALT45a57b911740c0a953fcf373807f28d1e4a963b6&click_sum=e9885132&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=turquoise+jewelry&ref=search_grid-882401-14-20&sr_prefetch=1&pf_from=search&pro=1&cns=1&sts=1&content_source=2ed48753-436f-4083-9571-6ba7e17e2d61%253ALT45a57b911740c0a953fcf373807f28d1e4a963b6',
